{
  "requirements": [
    {
      "text": "The system shall optimize path planning to achieve a minimum 30% reduction in average travel time compared to baseline scenarios.",
      "kaos_level": "tactical",
      "rationale": "This ensures efficient routing, contributing to overall performance efficiency."
    },
    {
      "text": "The system shall maintain a jerk value below 0.5 m/s³ during normal operation to enhance passenger comfort.",
      "kaos_level": "operational",
      "rationale": "Minimizing jerk directly impacts smoothness and responsiveness, essential for user experience."
    },
    {
      "text": "The system shall execute Minimal Risk Maneuvers within 5 seconds of detecting critical failures to ensure safety without compromising performance.",
      "kaos_level": "tactical",
      "rationale": "Timely MRM execution is crucial for maintaining operational efficiency while ensuring safety."
    },
    {
      "text": "The system shall continuously monitor ODD compliance with a latency of no more than 100 milliseconds to ensure real-time responsiveness.",
      "kaos_level": "operational",
      "rationale": "Low latency in monitoring enhances responsiveness and efficiency in decision-making."
    },
    {
      "text": "The system shall achieve at least 95% success rate in optimal speed profile generation during path planning.",
      "kaos_level": "tactical",
      "rationale": "High success rates in speed optimization directly influence throughput and overall system performance."
    },
    {
      "text": "The system shall utilize iterative quadratic programming to handle non-convex obstacle constraints with a processing time under 50 milliseconds.",
      "kaos_level": "operational",
      "rationale": "Efficient processing times are essential for maintaining high responsiveness in dynamic environments."
    },
    {
      "text": "The system shall prioritize smoothness over speed during emergency maneuvers to ensure a smooth transition without exceeding jerk limits.",
      "kaos_level": "strategic",
      "rationale": "Balancing smoothness during emergencies contributes to overall performance efficiency and user comfort."
    }
  ]
}
